def inner(groups,count):
 buckets=[[] for _ in range(min(3,len(groups)))];n=[0]*len(buckets)
 for g in sorted(groups,key=lambda g:(-count[g],g)):
  j=min(range(len(n)),key=lambda j:(n[j],j));buckets[j].append(g);n[j]+=count[g]
 return [dict(train_groups=sorted(set(groups)-set(b)),validation_groups=b) for b in buckets]
