 groups=sorted(set(counts)-set(f['test_groups']));ii=inner(groups,counts);final=min(range(len(ii)),key=lambda j:(sum(counts[g] for g in ii[j]['validation_groups']),j));pop.append(dict(name=f'outer{f["fold"]}',test_groups=f['test_groups'],inner=ii,final_validation_fold=final))
